package com.svc.voice;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Durable resumable uploads. root MUST be a dedicated directory below private filesDir.
 * POST /api/v1/uploads {size,sha256?}; PUT /uploads/id/chunks/index (raw body);
 * GET /uploads/id; POST /uploads/id/complete {name}; DELETE /uploads/id.
 * All paths above have /api/v1 prefix. One live store per root is enforced.
 * Importer.tryAcquire runs synchronously before 202; null means Busy (409).
 * Lease.importFile runs on worker, must check Cancellation before publication;
 * Lease.close always releases Busy. Its result must be JSON serializable.
 */
public final class UploadStore implements AutoCloseable {
 public static final long CHUNK=8L<<20, MAX_FILE=4L<<30, MAX_RESERVED=8L<<30, TTL=86400000L;
 // Budget includes upload + merged ZIP + bounded 8 GiB extraction + 4 GiB import staging.
 public static final long IMPORT_BUDGET=12L<<30, HEADROOM=64L<<20;
 public interface Publication { void publish() throws Exception; }
 public interface Cancellation { boolean cancelled(); default void commit(Publication action)throws Exception {check();action.publish();} default String uploadId(){return "";} default void check() throws IOException {if(cancelled())throw new IOException("Upload cancelled");} }
 public interface Lease extends AutoCloseable { Object importFile(File zip,String name,Cancellation cancel)throws Exception; void close(); }
 public interface Importer { Lease tryAcquire()throws Exception; }
 private static final String PREFIX="/api/v1/uploads";
 private final File root; private final Importer importer;
 private final Map<String,Session> sessions=new ConcurrentHashMap<>();
 private final ExecutorService worker=Executors.newSingleThreadExecutor();
 private final ScheduledExecutorService timer=Executors.newSingleThreadScheduledExecutor();
 private final java.nio.channels.FileChannel lockChannel; private final java.nio.channels.FileLock processLock;
 private final java.util.concurrent.locks.ReentrantReadWriteLock lifecycle=new java.util.concurrent.locks.ReentrantReadWriteLock();
 private volatile boolean closed; private final java.util.concurrent.atomic.AtomicLong reserved=new java.util.concurrent.atomic.AtomicLong();
 private static class Fault extends Exception {final int code;Fault(int c,String m){super(m);code=c;}}
 private static class Session {String filename="",id,sha="",task="",state="uploading",error="",name="";long size,touched;Object result=JSONObject.NULL;volatile boolean cancel,active;boolean released;Map<Integer,String> hashes=new TreeMap<>();File dir;}
 public UploadStore(File directory,Importer callback)throws IOException {
  importer=Objects.requireNonNull(callback);root=directory.getAbsoluteFile();
  rejectLinks(root.toPath());Files.createDirectories(root.toPath());rejectLinks(root.toPath());
  if(!root.isDirectory())throw new IOException("Upload root is not a directory");
  File lf=new File(root,".lock");safe(lf);lockChannel=java.nio.channels.FileChannel.open(lf.toPath(),StandardOpenOption.CREATE,StandardOpenOption.WRITE,LinkOption.NOFOLLOW_LINKS);
  try{processLock=lockChannel.tryLock();if(processLock==null)throw new IOException("Upload root already open");}catch(Exception e){lockChannel.close();throw new IOException("Upload root already open",e);}
  try{scan();}catch(Exception e){processLock.release();lockChannel.close();throw new IOException("Invalid upload storage",e);}
  timer.scheduleWithFixedDelay(()->{try{expire();}catch(Exception ignored){}},1,1,TimeUnit.HOURS);
 }
 private static void rejectLinks(Path p)throws IOException {for(Path q=p.toAbsolutePath();q!=null;q=q.getParent())if(Files.isSymbolicLink(q))throw new IOException("Symbolic link forbidden");}
 private static void safe(File f)throws IOException {rejectLinks(f.toPath());}
 private static JSONObject obj(Object... pairs)throws JSONException {JSONObject o=new JSONObject();for(int i=0;i<pairs.length;i+=2)o.put((String)pairs[i],pairs[i+1]);return o;}
 private static String random(){return UUID.randomUUID().toString().replace("-","");}
 private static boolean id(String s){return s!=null&&s.matches("[0-9a-f]{32}");}
 private static boolean terminal(Session s){return s.state.equals("succeeded")||s.state.equals("failed")||s.state.equals("cancelled")||s.state.equals("uploading");}
 private static long number(JSONObject o,String key)throws Exception {Object v=o.get(key);if(!(v instanceof Number)||v instanceof Double||v instanceof Float)throw new Fault(400,key+" must be an integer");return ((Number)v).longValue();}
 private static JSONObject body(LocalHttpWire.Request r)throws Exception {if(r.body==null||r.body.length()>32768)throw new Fault(400,"JSON body required (max 32 KiB)");safe(r.body);try{return new JSONObject(new String(Files.readAllBytes(r.body.toPath()),StandardCharsets.UTF_8));}catch(JSONException e){throw new Fault(400,"Invalid JSON");}}
 public LocalHttpWire.Reply handle(LocalHttpWire.Request r){lifecycle.readLock().lock();try{return handleInternal(r);}finally{lifecycle.readLock().unlock();}}
 private LocalHttpWire.Reply handleInternal(LocalHttpWire.Request r){try{if(closed)throw new Fault(409,"Upload store closed");return route(r);}catch(Exception e){int code=e instanceof Fault?((Fault)e).code:e instanceof JSONException?400:500;try{return new LocalHttpWire.Reply(code,obj("error",obj("code",code,"message",code==500?"Upload storage failure":e.getMessage())).toString());}catch(Exception ignored){return new LocalHttpWire.Reply(500,"{}");}}}
 private LocalHttpWire.Reply reply(int code,Session s)throws Exception {return new LocalHttpWire.Reply(code,status(s).toString());}
 private LocalHttpWire.Reply route(LocalHttpWire.Request r)throws Exception {
  if(PREFIX.equals(r.path)&&"POST".equals(r.method)){JSONObject b=body(r);long size=number(b,"total_size");if(size<1||size>MAX_FILE)throw new Fault(400,"total_size must be 1..4294967296");String filename=b.getString("filename");if(filename.isEmpty()||filename.length()>255||filename.equals(".")||filename.equals("..")||filename.matches(".*[\\\\/\\p{Cntrl}].*"))throw new Fault(400,"Invalid filename");String sha=b.has("sha256")?b.getString("sha256").toLowerCase(Locale.ROOT):"";if(!sha.isEmpty()&&!sha.matches("[0-9a-f]{64}"))throw new Fault(400,"Invalid sha256");synchronized(this){if(closed)throw new Fault(409,"Upload store closed");expire();if(reserved.get()+size>MAX_RESERVED)throw new Fault(409,"8 GiB reservation limit");space(size*2+IMPORT_BUDGET+HEADROOM+remaining());Session s=new Session();s.id=random();s.dir=new File(root,s.id);s.size=size;s.sha=sha;s.filename=filename;s.touched=System.currentTimeMillis();Files.createDirectory(s.dir.toPath());save(s);sessions.put(s.id,s);reserved.addAndGet(size);return reply(201,s);}}
  if(r.path==null||!r.path.startsWith(PREFIX+"/"))throw new Fault(404,"Upload route not found");String[] p=r.path.substring(PREFIX.length()+1).split("/",-1);if(!id(p[0]))throw new Fault(400,"Invalid upload id");Session s=sessions.get(p[0]);if(s==null)throw new Fault(404,"Upload not found");
  synchronized(s){safe(s.dir);if(closed)throw new Fault(409,"Upload store closed");if(sessions.get(s.id)!=s)throw new Fault(404,"Upload expired");
   if(p.length==1&&r.method.equals("GET")){touch(s);return reply(200,s);}
   if(p.length==1&&r.method.equals("DELETE")){s.cancel=true;if(s.state.equals("succeeded")){s.cancel=false;return reply(200,s);}if(!s.active){s.state="cancelled";s.error="Cancelled";touch(s);discard(s);}return reply(200,s);}
   if(p.length==3&&p[1].equals("chunks")&&r.method.equals("PUT")){if(s.active||s.state.equals("succeeded")||s.cancel)throw new Fault(409,"Session does not accept chunks");if(!p[2].matches("0|[1-9][0-9]{0,2}"))throw new Fault(400,"Invalid chunk index");int index=Integer.parseInt(p[2]);long count=(s.size+CHUNK-1)/CHUNK;if(index>=count)throw new Fault(400,"Chunk index out of range");long expected=Math.min(CHUNK,s.size-index*CHUNK);if(r.body==null||r.body.length()!=expected)throw new Fault(400,"Chunk size mismatch");safe(r.body);File dest=chunk(s,index),tmp=new File(s.dir,"chunk.tmp");safe(dest);safe(tmp);space(expected+HEADROOM);try{String hash=copyHash(r.body,tmp,expected,null);if(dest.exists()){if(dest.length()!=expected||!hash.equals(hash(dest,null)))throw new Fault(409,"Chunk content conflict");}else atomic(tmp,dest);s.hashes.put(index,hash);s.state="uploading";s.error="";touch(s);return reply(200,s);}finally{Files.deleteIfExists(tmp.toPath());}}
   if(p.length==2&&p[1].equals("complete")&&r.method.equals("POST")){JSONObject b=body(r);String name=b.getString("name");if(name.isEmpty()||name.length()>100||name.startsWith(".")||!name.matches("[\\p{L}\\p{N}_ .-]+"))throw new Fault(400,"Invalid role name");if(s.active||s.state.equals("succeeded")){if(!s.name.equals(name))throw new Fault(409,"Complete name conflict");touch(s);return reply(s.active?202:200,s);}if(s.cancel)throw new Fault(409,"Session cancelled");for(int i=0;i<(s.size+CHUNK-1)/CHUNK;i++){File f=chunk(s,i);safe(f);if(!f.isFile()||f.length()!=Math.min(CHUNK,s.size-i*CHUNK))throw new Fault(409,"Missing or invalid chunk "+i);}space(s.size+IMPORT_BUDGET+HEADROOM);Lease lease=importer.tryAcquire();if(lease==null)throw new Fault(409,"Engine busy; chunks retained");boolean submitted=false;try{s.task=random();s.name=name;s.state="queued";s.error="";s.result=JSONObject.NULL;s.active=true;touch(s);worker.execute(()->run(s,lease));submitted=true;return reply(202,s);}finally{if(!submitted){s.active=false;s.state="failed";s.error="Could not schedule import";try{save(s);}finally{lease.close();}}}}
   throw new Fault(404,"Upload route not found");
  }
 }
 private void run(Session s,Lease lease){File merged=new File(s.dir,"merged.zip");try{synchronized(s){s.state="running";touch(s);}Cancellation cancel=new Cancellation(){public boolean cancelled(){return s.cancel;}public String uploadId(){return s.id;}public void commit(Publication action)throws Exception{synchronized(s){check();action.publish();}}};MessageDigest md=MessageDigest.getInstance("SHA-256");safe(merged);try(FileOutputStream out=new FileOutputStream(merged)){byte[] buf=new byte[65536];for(int i=0;i<(s.size+CHUNK-1)/CHUNK;i++){cancel.check();File part=chunk(s,i);safe(part);MessageDigest partHash=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(part.toPath(),LinkOption.NOFOLLOW_LINKS)){long n=0;int k;while((k=in.read(buf))!=-1){cancel.check();n+=k;if(n>Math.min(CHUNK,s.size-i*CHUNK))throw new IOException("Chunk changed");md.update(buf,0,k);partHash.update(buf,0,k);out.write(buf,0,k);}if(n!=Math.min(CHUNK,s.size-i*CHUNK))throw new IOException("Chunk truncated");String expectedHash=s.hashes.get(i);if(expectedHash==null||!expectedHash.equals(hex(partHash.digest())))throw new IOException("Saved chunk hash mismatch");}}out.getFD().sync();}String digest=hex(md.digest());if(!s.sha.isEmpty()&&!s.sha.equals(digest))throw new IOException("SHA-256 mismatch");cancel.check();Object result=lease.importFile(merged,s.name,cancel);synchronized(s){s.result=result==null?JSONObject.NULL:result;s.state="succeeded";s.error="";try{touch(s);}catch(Exception e){s.state="failed";throw e;}release(s);}for(int i=0;i<(s.size+CHUNK-1)/CHUNK;i++)try{Files.deleteIfExists(chunk(s,i).toPath());}catch(IOException ignored){}}catch(Throwable e){synchronized(s){s.state=s.cancel?"cancelled":"failed";s.error=String.valueOf(e.getMessage());try{touch(s);}catch(Exception ignored){}}}finally{try{Files.deleteIfExists(merged.toPath());}catch(Exception ignored){}try{lease.close();}finally{synchronized(s){s.active=false;if(s.cancel)try{discard(s);}catch(Exception ignored){}s.notifyAll();}}}}
 private static File chunk(Session s,int n){return new File(s.dir,"chunk-"+n);}
 private JSONObject status(Session s)throws Exception {JSONArray received=new JSONArray(),missing=new JSONArray();for(int i=0;i<(s.size+CHUNK-1)/CHUNK;i++){File f=chunk(s,i);safe(f);if(f.isFile()&&s.hashes.containsKey(i)&&f.length()==Math.min(CHUNK,s.size-i*CHUNK))received.put(i);else if(!s.state.equals("succeeded"))missing.put(i);}return obj("filename",s.filename,"total_size",s.size,"chunk_size",CHUNK,"total_chunks",(s.size+CHUNK-1)/CHUNK,"missing_chunks",missing,"task_id",s.task,"id",s.id,"size",s.size,"chunkSize",CHUNK,"sha256",s.sha,"received",received,"taskId",s.task,"state",s.state,"error",s.error,"result",s.result,"name",s.name,"cancelRequested",s.cancel,"updatedAt",s.touched);}
 private void touch(Session s)throws Exception{s.touched=System.currentTimeMillis();save(s);}
 private void save(Session s)throws Exception {JSONObject h=new JSONObject();for(Map.Entry<Integer,String> e:s.hashes.entrySet())h.put(String.valueOf(e.getKey()),e.getValue());JSONObject o=obj("chunk_hashes",h,"filename",s.filename,"version",1,"id",s.id,"size",s.size,"sha256",s.sha,"taskId",s.task,"state",s.state,"name",s.name,"error",s.error,"result",s.result,"cancel",s.cancel,"updatedAt",s.touched);if(o.toString().getBytes(StandardCharsets.UTF_8).length>65536)throw new IOException("Task metadata exceeds 64 KiB");File tmp=new File(s.dir,"meta.tmp"),dest=new File(s.dir,"meta.json");safe(tmp);safe(dest);try(FileOutputStream out=new FileOutputStream(tmp)){out.write(o.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}atomic(tmp,dest);}
 private static void atomic(File from,File to)throws IOException {safe(from);safe(to);Files.move(from.toPath(),to.toPath(),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}
 private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private static String hash(File f,Cancellation c)throws Exception {return copyHash(f,null,f.length(),c);}
 private static String copyHash(File from,File to,long size,Cancellation c)throws Exception {safe(from);MessageDigest md=MessageDigest.getInstance("SHA-256");try(InputStream in=Files.newInputStream(from.toPath(),LinkOption.NOFOLLOW_LINKS);FileOutputStream out=to==null?null:new FileOutputStream(to)){byte[] b=new byte[65536];long n=0;int k;while((k=in.read(b))!=-1){if(c!=null)c.check();n+=k;if(n>size)throw new IOException("Body grew");md.update(b,0,k);if(out!=null)out.write(b,0,k);}if(n!=size)throw new IOException("Body truncated");if(out!=null)out.getFD().sync();}return hex(md.digest());}
 private void space(long bytes)throws Fault {if(root.getUsableSpace()<bytes)throw new Fault(507,"Insufficient disk budget (upload + merge + extraction + import)");}
 private long remaining(){long n=0;for(Session s:sessions.values())if(!s.released)n+=s.size;return n;}
 private void scan()throws Exception {File[] dirs=root.listFiles();if(dirs==null)throw new IOException("Cannot scan uploads");for(File d:dirs){if(d.getName().equals(".lock"))continue;if(!id(d.getName()))throw new IOException("Unexpected upload root entry");safe(d);if(!d.isDirectory())throw new IOException("Invalid session directory");File meta=new File(d,"meta.json");safe(meta);if(!meta.isFile()||meta.length()>65536)throw new IOException("Missing/oversized upload metadata");JSONObject o=new JSONObject(new String(Files.readAllBytes(meta.toPath()),StandardCharsets.UTF_8));Session s=new Session();s.dir=d;s.id=d.getName();s.size=number(o,"size");if(o.getInt("version")!=1||!s.id.equals(o.getString("id"))||s.size<1||s.size>MAX_FILE)throw new IOException("Invalid metadata");JSONObject h=o.optJSONObject("chunk_hashes");if(h!=null)for(Iterator<String> keys=h.keys();keys.hasNext();){String key=keys.next();if(!key.matches("0|[1-9][0-9]{0,2}")||Integer.parseInt(key)>=(s.size+CHUNK-1)/CHUNK||!h.getString(key).matches("[0-9a-f]{64}"))throw new IOException("Invalid chunk hash metadata");s.hashes.put(Integer.parseInt(key),h.getString(key));}s.filename=o.optString("filename","");s.sha=o.getString("sha256");s.task=o.getString("taskId");s.state=o.getString("state");s.name=o.getString("name");s.error=o.getString("error");s.result=o.opt("result");s.cancel=o.getBoolean("cancel");s.touched=number(o,"updatedAt");if((!s.sha.isEmpty()&&!s.sha.matches("[0-9a-f]{64}"))||(!s.task.isEmpty()&&!id(s.task))||!Arrays.asList("uploading","queued","running","succeeded","failed","cancelled").contains(s.state)||s.touched<0)throw new IOException("Invalid session fields");File[] entries=d.listFiles();if(entries==null)throw new IOException("Unreadable session");for(File f:entries){safe(f);if(!f.isFile())throw new IOException("Invalid session entry");String n=f.getName();if(n.equals("meta.json"))continue;if(n.equals("meta.tmp")||n.equals("chunk.tmp")||n.equals("merged.zip")){Files.delete(f.toPath());continue;}if(!n.matches("chunk-(0|[1-9][0-9]{0,2})"))throw new IOException("Unexpected session entry");int i=Integer.parseInt(n.substring(6));if(i>=(s.size+CHUNK-1)/CHUNK||f.length()!=Math.min(CHUNK,s.size-i*CHUNK))throw new IOException("Invalid saved chunk");}if(!terminal(s)){s.state="failed";s.error="Interrupted by restart; retry complete (verify role publication first)";save(s);}sessions.put(s.id,s);if(!s.state.equals("succeeded")&&!s.state.equals("cancelled"))reserved.addAndGet(s.size);else{s.released=true;discard(s);}if(reserved.get()>MAX_RESERVED)throw new IOException("Reservation limit exceeded");}expire();}
 private void expire()throws IOException {long now=System.currentTimeMillis();for(Session s:sessions.values()){synchronized(s){if(sessions.get(s.id)!=s||s.active||now-s.touched<TTL)continue;safe(s.dir);File[] entries=s.dir.listFiles();if(entries==null)throw new IOException("Unreadable expired session");for(File f:entries){safe(f);if(!f.isFile()||!f.getName().matches("meta\\.(json|tmp)|chunk\\.tmp|merged\\.zip|chunk-(0|[1-9][0-9]{0,2})"))throw new IOException("Unexpected expired entry");Files.delete(f.toPath());}Files.delete(s.dir.toPath());if(sessions.remove(s.id,s))release(s);}}}
 private void release(Session s){if(!s.released){s.released=true;reserved.addAndGet(-s.size);}}
 private void discard(Session s)throws IOException{for(int i=0;i<(s.size+CHUNK-1)/CHUNK;i++){File f=chunk(s,i);safe(f);Files.deleteIfExists(f.toPath());}release(s);}
 /** Stop listener first. Waits for tasks; never erases resumable sessions. */
 public void close(){lifecycle.writeLock().lock();try{closeInternal();}finally{lifecycle.writeLock().unlock();}}
 private void closeInternal(){synchronized(this){if(closed)return;closed=true;timer.shutdownNow();worker.shutdown();}boolean interrupted=false;for(;;)try{if(worker.awaitTermination(1,TimeUnit.SECONDS))break;}catch(InterruptedException e){interrupted=true;}try{processLock.release();lockChannel.close();}catch(IOException ignored){}if(interrupted)Thread.currentThread().interrupt();}
}
